sys_ux_client_script.script:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
* @param {ApiHelpers} params.helpers
*/
function handler({api, event, helpers, imports}) {
    let records = structuredClone(api.state.records);
    let pos = records.findIndex(rec => rec.checked == true);
    // let pos = 1;
    console.warn(records,pos);
    if (pos < 0) {
        console.warn(records,pos);
        console.warn("選択されていません");
        return;
    }
    records[pos].checked = false;

    records.splice(pos, 1);

    // 浅いコピーなのでNG？
    // api.setState("records", records.map(v => {v.checked = false; return v; }));
    // api.setState("records", [...api.state.records]);

    api.setState("records", records);
}
